<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
   wall              → BoxGeometry(0.04, 4.0, 2.6) white + EdgesGeometry black
   barrier (b only)  → BoxGeometry(0.04, 4.0, 2.6) pure black
   pinhole           → CircleGeometry(1) white, scaled by aperture slider (x2 faces)
   trunk             → LatheGeometry(flared profile)  brown #6E3F17
   branches          → 2 × TubeGeometry(CatmullRomCurve3) brown
   canopy            → 6 × SphereGeometry (2 dark #1E9B12 behind, 4 bright #35D707 front)
   rays              → CylinderGeometry shaft + ConeGeometry arrowhead at wall end
   projected image   → ShapeGeometry trunk + CircleGeometry blobs, pale, 12 ghost copies
   probe marker      → RingGeometry orange on wall
   labels            → Wall / Pinhole / (a) / (b) serif HTML labels
   ─────────────────────────────────────────────────────────────────────── */

const PC_SERIF = 'Georgia, "Times New Roman", serif';
const C_BROWN = 0x6E3F17, C_GREEN = 0x35D707, C_GREEN2 = 0x3FE014, C_GDARK = 0x1E9B12;
const C_PTRUNK = 0xC8A98C, C_PG1 = 0xA9E8A0, C_PG2 = 0x7FD07A;

const WALL_X = -3.2, WALL_F = -3.17, BAR_X = -0.6, TREE_X = 2.4, PIN_Y = 0.35;
const PIN = new THREE.Vector3(BAR_X, PIN_Y, 0);
const AZ_DEG = 58;

/* ── canopy blobs (tree-local) ─────────────────────────────────────────── */
const BLOBS = [
  { p: [-0.35, 1.55, -0.45], r: 0.78, c: C_GDARK },
  { p: [0.55, 1.30, -0.45], r: 0.72, c: C_GDARK },
  { p: [-0.05, 1.50, 0.18], r: 0.78, c: C_GREEN },
  { p: [-0.62, 1.05, 0.15], r: 0.80, c: C_GREEN2 },
  { p: [0.38, 0.92, 0.30], r: 0.76, c: C_GREEN },
  { p: [-1.05, 0.78, -0.10], r: 0.58, c: C_GREEN2 }
];
const TRUNK_PROF = [[0.45, -1.60], [0.30, -1.32], [0.235, -0.95], [0.20, -0.20], [0.175, 0.45]];

/* ── ray sources (world) ───────────────────────────────────────────────── */
const SRC = [
  { p: [TREE_X - 0.05, 2.10, 0.18], c: C_GREEN },
  { p: [TREE_X - 1.05, 0.85, -0.10], c: C_GREEN },
  { p: [TREE_X + 0.38, 1.05, 0.35], c: C_GREEN },
  { p: [TREE_X, -1.45, 0.10], c: C_BROWN },
  { p: [TREE_X - 0.16, -0.80, 0.14], c: C_BROWN },
  { p: [TREE_X + 0.18, -0.20, 0.12], c: C_BROWN },
  { p: [TREE_X - 0.60, 0.52, 0.03], c: C_BROWN },
  { p: [TREE_X + 0.60, 0.52, 0.03], c: C_BROWN }
];
const P_UP = new THREE.Vector3(WALL_F, 1.05, 0.15);
const P_LO = new THREE.Vector3(WALL_F, -0.75, -0.10);
const A_TARGET = [P_UP, P_LO, P_UP, P_UP, P_LO, P_LO, P_UP, P_LO];

/* ── helpers ───────────────────────────────────────────────────────────── */
function pcRay(from, to, color, opts) {
  opts = opts || {};
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 1e-6) return g;
  const n = dir.clone().normalize();
  const headLen = opts.head === false ? 0 : (opts.headLen || 0.26);
  const shaftR = opts.shaftR || 0.022;
  const op = (opts.opacity == null) ? 1 : opts.opacity;
  const mat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: op });
  mat.userData.base = op;
  const sl = Math.max(0.001, len - headLen);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 7), mat);
  sh.quaternion.copy(q);
  sh.position.copy(from).addScaledVector(n, sl / 2);
  g.add(sh);
  if (headLen > 0) {
    const hd = new THREE.Mesh(new THREE.ConeGeometry(opts.headR || 0.085, headLen, 12), mat);
    hd.quaternion.copy(q);
    hd.position.copy(to).addScaledVector(n, -headLen / 2);
    g.add(hd);
  }
  g.userData.mat = mat;
  return g;
}

function pcDisposeChildren(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i];
    o.traverse(x => {
      if (x.geometry) x.geometry.dispose();
      if (x.material) { Array.isArray(x.material) ? x.material.forEach(m => m.dispose()) : x.material.dispose(); }
    });
    g.remove(o);
  }
}

function pcBuildTree() {
  const g = new THREE.Group();
  const bm = new THREE.MeshBasicMaterial({ color: C_BROWN });
  const prof = TRUNK_PROF.map(p => new THREE.Vector2(p[0], p[1]));
  g.add(new THREE.Mesh(new THREE.LatheGeometry(prof, 22), bm));
  const mkBranch = (sx) => {
    const pts = [
      new THREE.Vector3(sx * 0.16, -0.06, 0.0),
      new THREE.Vector3(sx * 0.45, 0.02, 0.02),
      new THREE.Vector3(sx * 0.63, 0.22, 0.02),
      new THREE.Vector3(sx * 0.60, 0.53, 0.0)
    ];
    return new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 26, 0.075, 10, false), bm);
  };
  g.add(mkBranch(-1)); g.add(mkBranch(1));
  BLOBS.forEach(b => {
    const m = new THREE.Mesh(new THREE.SphereGeometry(b.r, 22, 16), new THREE.MeshBasicMaterial({ color: b.c }));
    m.position.set(b.p[0], b.p[1], b.p[2]);
    g.add(m);
  });
  g.position.set(TREE_X, 0, 0);
  return g;
}

/* projected (inverted) image, one "ghost" copy */
function pcBuildProjection() {
  const grp = new THREE.Group();
  grp.rotation.y = -Math.PI / 2;      // local x → world +Z, local y → world +Y
  const mats = [];
  const s0 = 2.6 / (TREE_X - BAR_X);
  // trunk silhouette, inverted (points UP on the wall)
  const shp = new THREE.Shape();
  TRUNK_PROF.forEach((pt, i) => {
    const y = PIN_Y + s0 * (PIN_Y - pt[1]);
    const hw = s0 * pt[0];
    if (i === 0) shp.moveTo(-hw, y); else shp.lineTo(-hw, y);
  });
  for (let i = TRUNK_PROF.length - 1; i >= 0; i--) {
    shp.lineTo(s0 * TRUNK_PROF[i][0], PIN_Y + s0 * (PIN_Y - TRUNK_PROF[i][1]));
  }
  const tm = new THREE.MeshBasicMaterial({
    color: C_PTRUNK, transparent: true, opacity: 0.45,
    side: THREE.DoubleSide, depthWrite: false
  });
