<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
   wall              → PlaneGeometry(3.1, 4.6) white DoubleSide  (single quad)
   wall outline      → LineLoop over the 4 wall corners, black, ONE outline only
   barrier (b only)  → PlaneGeometry(3.1, 4.6) pure black DoubleSide
   pinhole           → 2 × CircleGeometry(1) white ellipse, scaled by slider
   trunk             → LatheGeometry(flared profile)  brown #6E3F17
   branches          → 2 × TubeGeometry(CatmullRomCurve3) brown, in FRONT of canopy
   canopy            → 7 × SphereGeometry (3 dark #1E9B12 behind, 4 bright #35D707 front,
                        all lifted above the branch tips so branches stay visible)
   rays              → thin CylinderGeometry shaft (r=0.011) + big ConeGeometry head
   projected image   → ShapeGeometry trunk + CircleGeometry blobs, pale, 12 ghost copies
   probe marker      → RingGeometry orange on wall
   labels            → Wall / Pinhole / (a) / (b) large serif HTML labels
   ─────────────────────────────────────────────────────────────────────── */

const PC_SERIF = 'Georgia, "Times New Roman", serif';
const C_BROWN = 0x6E3F17, C_GREEN = 0x35D707, C_GREEN2 = 0x3FE014, C_GDARK = 0x1E9B12;
const C_PTRUNK = 0xC8A98C, C_PG1 = 0xA9E8A0, C_PG2 = 0x7FD07A;

const WALL_X = -3.2, WALL_F = -3.185, BAR_X = -0.6, TREE_X = 2.4, PIN_Y = 0.35;
const WALL_H = 4.6, WALL_D = 3.1;                 // wall / barrier extent (single quad)
const TREE_S = 0.85;                              // tree scale (wall must read bigger)
const MAG = (BAR_X - WALL_X) / (TREE_X - BAR_X);  // 2.6 / 3.0 = 0.867
const PIN = new THREE.Vector3(BAR_X, PIN_Y, 0);
const AZ_DEG = 58, EL_DEG = 6;

/* ── canopy blobs (tree-local, pre-scale) — lifted so branches show ────── */
const BLOBS = [
  { p: [-0.05, 1.98, -0.52], r: 0.80, c: C_GDARK },   // back-top dark lobe
  { p: [0.95, 1.38, -0.46], r: 0.72, c: C_GDARK },   // back-right dark lobe
  { p: [0.70, 0.80, -0.50], r: 0.58, c: C_GDARK },   // lower-right dark lobe
  { p: [0.38, 1.72, 0.05], r: 0.70, c: C_GREEN },   // upper bright
  { p: [-0.62, 1.50, 0.16], r: 0.78, c: C_GREEN2 },  // left bright
  { p: [-0.10, 1.20, 0.34], r: 0.82, c: C_GREEN },   // big front lobe
  { p: [-1.15, 1.08, 0.04], r: 0.56, c: C_GREEN2 }   // far-left bright
];
const TRUNK_PROF = [[0.50, -2.00], [0.34, -1.60], [0.25, -1.10], [0.21, -0.30], [0.19, 0.60]];
const BR_TIP_Y = 0.40, BR_TIP_X = 0.55, BR_Z = 0.30;

/* ── ray sources (tree-local) → world ──────────────────────────────────── */
function twp(l) { return new THREE.Vector3(TREE_X + TREE_S * l[0], TREE_S * l[1], TREE_S * l[2]); }
const SRC = [
  { l: [-0.05, 1.98, -0.52], c: C_GDARK, up: true },            // dark canopy top
  { l: [0.38, 1.72, 0.05], c: C_GREEN, up: false },           // bright canopy
  { l: [-1.15, 1.08, 0.04], c: C_GREEN2, up: true },            // left canopy
  { l: [0.00, -1.70, 0.05], c: C_BROWN, up: true },            // trunk base
  { l: [-0.10, -0.50, 0.15], c: C_BROWN, up: false },           // mid trunk
  { l: [0.15, 0.30, 0.15], c: C_BROWN, up: true },            // upper trunk
  { l: [-BR_TIP_X, BR_TIP_Y, BR_Z], c: C_BROWN, up: false },   // left branch tip
  { l: [BR_TIP_X, BR_TIP_Y, BR_Z], c: C_BROWN, up: false }    // right branch tip
];
const P_UP = new THREE.Vector3(WALL_F, 1.05, 0.15);
const P_LO = new THREE.Vector3(WALL_F, -0.75, -0.10);

/* ── helpers ───────────────────────────────────────────────────────────── */
function pcRay(from, to, color, opts) {
  opts = opts || {};
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 1e-6) return g;
  const n = dir.clone().normalize();
  const headLen = opts.head === false ? 0 : (opts.headLen || 0.30);
  const shaftR = opts.shaftR || 0.011;
  const op = (opts.opacity == null) ? 1 : opts.opacity;
  const mat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: op });
  mat.userData.base = op;
  const sl = Math.max(0.001, len - headLen);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 6), mat);
  sh.quaternion.copy(q);
  sh.position.copy(from).addScaledVector(n, sl / 2);
  g.add(sh);
  if (headLen > 0) {
    const hd = new THREE.Mesh(new THREE.ConeGeometry(opts.headR || 0.105, headLen, 16), mat);
    hd.quaternion.copy(q);
    hd.position.copy(to).addScaledVector(n, -headLen / 2);
    g.add(hd);
  }
  g.userData.mat = mat;
  return g;
}

function pcDisposeChildren(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const o = g.children[i];
    o.traverse(x => {
      if (x.geometry) x.geometry.dispose();
      if (x.material) { Array.isArray(x.material) ? x.material.forEach(m => m.dispose()) : x.material.dispose(); }
    });
    g.remove(o);
  }
}

function pcBuildTree() {
  const g = new THREE.Group();
  const bm = new THREE.MeshBasicMaterial({ color: C_BROWN });
  const prof = TRUNK_PROF.map(p => new THREE.Vector2(p[0], p[1]));
  g.add(new THREE.Mesh(new THREE.LatheGeometry(prof, 24), bm));
  // curved branch stubs: out from the trunk, dipping, then hooking upward.
  const mkBranch = (sx) => {
    const pts = [
      new THREE.Vector3(sx * 0.16, -0.16, BR_Z * 0.45),
      new THREE.Vector3(sx * 0.40, -0.16, BR_Z * 0.85),
      new THREE.Vector3(sx * 0.58, 0.02, BR_Z),
      new THREE.Vector3(sx * BR_TIP_X, BR_TIP_Y, BR_Z)
    ];
    return new THREE.Mesh(
      new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 28, 0.075, 10, false), bm);
  };
  g.add(mkBranch(-1)); g.add(mkBranch(1));
  BLOBS.forEach(b => {
    const m = new THREE.Mesh(new THREE.SphereGeometry(b.r, 26, 18),
      new THREE.MeshBasicMaterial({ color: b.c }));
    m.position.set(b.p[0], b.p[1], b.p[2]);
    g.add(m);
  });
  g.position.set(TREE_X, 0, 0);
  g.scale.setScalar(TREE_S);
  return g;
}

/* projected (inverted) image, one "ghost" copy */
function pcBuildProjection() {
  const grp = new THREE.Group();
  grp.rotation.y = -Math.PI / 2;      // local x → world +Z, local y → world +Y
  const mats = [];
  const s0 = MAG;
  // trunk silhouette, inverted (points UP on the wall)
  const shp = new THREE.Shape();
  TRUNK_PROF.forEach((pt, i) => {
    const y = PIN_Y + s0 * (PIN_Y - TREE_S * pt[1]);
    const hw = s0 * TREE_S * pt[0];
    if (i === 0) shp.moveTo(-hw, y); else shp.lineTo(-hw, y);
  });
  for (let i = TRUNK_PROF.length - 1; i >= 0; i--) {
    shp.lineTo(s0 * TREE_S * TRUNK_PROF[i][0], PIN_Y + s0 * (PIN_Y - TREE_S * TRUNK_PROF[i][1]));
  }
  const tm = new THREE.MeshBasicMaterial({
    color: C_PTRUNK, transparent: true, opacity: 0.45,
    side: THREE.DoubleSide, depthWrite: false
  });
  tm.userData.base = 0.45; mats.push(tm);
  grp.add(new THREE.Mesh(new THREE.ShapeGeometry(shp), tm));
  // canopy blobs, inverted, below the trunk
  BLOBS.forEach(b => {
    const W = twp(b.p);
    const s = (BAR_X - WALL_X) / (W.x - BAR_X);
    const y = PIN_Y + s * (PIN_Y - W.y);
    const z = -s * W.z;
    const op = (b.c === C_GDARK) ? 0.33 : 0.50;
    const m = new THREE.MeshBasicMaterial({
      color: (b.c === C_GDARK) ? C_PG2 : C_PG1, transparent: true,
      opacity: op, side: THREE.DoubleSide, depthWrite: false
    });
    m.userData.base = op; mats.push(m);
    const c = new THREE.Mesh(new THREE.CircleGeometry(b.r * TREE_S * s, 30), m);
    c.position.set(z, y, 0);
    grp.add(c);
  });
  return { group: grp, mats: mats };
}

/* ── panel builder ─────────────────────────────────────────────────────── */
function pcBuildPanel(mode) {
  const G = new THREE.Group();
  const P = { mode: mode, group: G, rayMats: [], labels: [], ghosts: [], probe: new THREE.Group() };

  // wall: ONE planar quad + ONE black outline
  const wallGeo = new THREE.PlaneGeometry(WALL_D, WALL_H);
  const wall = new THREE.Mesh(wallGeo, new THREE.MeshBasicMaterial({
    color: 0xffffff, side: THREE.DoubleSide
  }));
  wall.rotation.y = Math.PI / 2;
  wall.position.set(WALL_X, 0, 0);
  G.add(wall); P.wall = wall;

  const hz = WALL_D / 2, hy = WALL_H / 2, ox = WALL_X + 0.008;
  const ring = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(ox, hy, hz), new THREE.Vector3(ox, hy, -hz),
      new THREE.Vector3(ox, -hy, -hz), new THREE.Vector3(ox, -hy, hz)
    ]),
    new THREE.LineBasicMaterial({ color: 0x000000 }));
  G.add(ring);

  registerInteractive(wall, {
    title: 'Wall (image plane)',
    tooltip: 'Click a spot to probe the rays reaching it',
    body: 'Every point on this wall collects whatever light can reach it. Without an aperture that is light from many scene directions at once, so the wall is a uniform wash. Click a point to see its incoming bundle.'
  });

  const tree = pcBuildTree();
  G.add(tree);
  registerInteractive(tree, {
    title: 'Scene object (tree)',
    tooltip: 'The scene: every surface point radiates in all directions',
    body: 'Each point of the trunk, branches and canopy scatters light in every direction. The trunk is drawn brown and the canopy green so you can tell which rays came from where.'
  });

  if (mode === 'b') {
    const bar = new THREE.Mesh(new THREE.PlaneGeometry(WALL_D, WALL_H),
      new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide }));
    bar.rotation.y = Math.PI / 2;
    bar.position.set(BAR_X, 0, 0);
    G.add(bar);
    registerInteractive(bar, {
      title: 'Opaque barrier',
      tooltip: 'Blocks every path except the pinhole',
      body: 'The barrier removes almost all scene-to-wall paths. Only rays that happen to pass through the single hole survive, so each wall point is restricted to essentially one scene direction.'
    });
    P.pinDiscs = [];
    [-1, 1].forEach(sg => {
      const dsc = new THREE.Mesh(new THREE.CircleGeometry(1, 28),
        new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }));
      dsc.position.set(BAR_X + sg * 0.012, PIN_Y, 0);
      dsc.rotation.y = Math.PI / 2;
      G.add(dsc); P.pinDiscs.push(dsc);
    });
    registerInteractive(P.pinDiscs[1], {
      title: 'Pinhole aperture',
      tooltip: 'The one surviving path — the centre of projection',
      body: 'All image-forming rays cross here, so the projection on the wall is inverted: canopy-top rays land low, trunk rays land high. Magnification m = 2.6 / 3.0 ≈ 0.87.'
    });
    for (let i = 0; i < 12; i++) {
      const gh = pcBuildProjection();
      gh.group.position.set(WALL_X + 0.05, 0, 0);
      G.add(gh.group);
      P.ghosts.push(gh);
    }
  }

  // rays — thin shafts, prominent arrowheads at the wall end
  SRC.forEach((s) => {
    const S = twp(s.l);
    if (mode === 'a') {
      const r = pcRay(S, s.up ? P_UP : P_LO, s.c, {});
      G.add(r); P.rayMats.push(r.userData.mat);
    } else {
      const sc = (BAR_X - WALL_X) / (S.x - BAR_X);
      const W = new THREE.Vector3(WALL_F, PIN_Y + sc * (PIN_Y - S.y), -sc * S.z);
      const r1 = pcRay(S, PIN, s.c, { head: false });
      const r2 = pcRay(PIN, W, s.c, {});
      G.add(r1); G.add(r2);
      P.rayMats.push(r1.userData.mat, r2.userData.mat);
    }
  });

  G.add(P.probe);

  // labels — large serif, matching the source's prominent captions
  const mkL = (txt, local, size, off) => {
    const e = addLabel(txt, new THREE.Vector3(0, 0, 0), { fontSize: size + 'px', offset: off || [0, 0] });
    e.div.style.fontFamily = PC_SERIF;
    P.labels.push({ e: e, local: local, base: size });
  };
  // 'Wall' sits just inside the near (screen-left) upper corner of the wall quad
  mkL('Wall', new THREE.Vector3(WALL_X, WALL_H / 2 - 0.12, WALL_D / 2 - 0.10), 34, [8, -14]);
  mkL(mode === 'a' ? '(a)' : '(b)', new THREE.Vector3(-0.3, -WALL_H / 2 - 0.30, 0.0), 40, [0, 14]);
  if (mode === 'b') mkL('Pinhole', new THREE.Vector3(BAR_X, WALL_H / 2 + 0.10, -0.45), 34, [10, -16]);

  return P;
}

const panelA = pcBuildPanel('a');
const panelB = pcBuildPanel('b');

/* ── state ─────────────────────────────────────────────────────────────── */
const pcState = { mode: 'a', layout: 'side', pin: 1 };
let pcProbeLocal = null;
let pcLastLayout = null;

function pcActive() {
  return pcState.layout === 'side' ? [panelA, panelB] : [pcState.mode === 'a' ? panelA : panelB];
}

function pcUpdateLabels() {
  const k = pcState.layout === 'side' ? 1.35 : 1.0;
  [panelA, panelB].forEach(P => {
    const on = !!P.group.parent;
    P.labels.forEach(L => {
      L.e.div.style.fontSize = Math.round(L.base * k) + 'px';
      if (on) L.e.pos.copy(L.local).add(P.group.position);
      else L.e.pos.set(1e6, 1e6, 1e6);
    });
  });
}

function pcApertureRadius(mm) { return 0.02 + (mm - 0.2) * (0.55 - 0.02) / 11.8; }

function pcSetPinhole(mm) {
  pcState.pin = mm;
  const lbl = document.getElementById('valPin');
  if (lbl) lbl.textContent = mm.toFixed(1);
  const sl = document.getElementById('slPin');
  if (sl && Math.abs(parseFloat(sl.value) - mm) > 1e-6) sl.value = mm;
  const r = pcApertureRadius(mm);
  if (panelB.pinDiscs) panelB.pinDiscs.forEach(dsc => dsc.scale.set(r, r * 1.5, 1));
  // blur = stacked ghost copies over the aperture disc
  const blurR = r * 1.867;
  const n = Math.max(1, Math.min(12, Math.round(1 + blurR * 11)));
  const a = 1 - Math.pow(1 - 0.5, 1 / n);
  panelB.ghosts.forEach((gh, i) => {
    if (i >= n) { gh.group.visible = false; return; }
    gh.group.visible = true;
    let dy = 0, dz = 0;
    if (n > 1) {
      const ang = i * 2.399963;
      const rad = blurR * Math.sqrt((i + 0.5) / n);
      dy = rad * Math.sin(ang) * 1.5; dz = rad * Math.cos(ang);
    }
    gh.group.position.set(WALL_X + 0.05 - i * 0.002, dy, dz);
    gh.mats.forEach(m => { m.opacity = m.userData.base * (a / 0.5); });
  });
  if (pcProbeLocal) pcApplyProbe();
}

/* ── probe ─────────────────────────────────────────────────────────────── */
const PROBE_SRC = SRC.map(s => ({ l: s.l.slice(), c: s.c })).concat([
  { l: [0.95, 1.38, -0.46], c: C_GDARK },
  { l: [0.70, 0.80, -0.50], c: C_GDARK },
  { l: [-0.62, 1.50, 0.16], c: C_GREEN2 },
  { l: [-0.10, 1.20, 0.34], c: C_GREEN },
  { l: [0.05, -1.10, 0.12], c: C_BROWN }
]);

function pcApplyProbe() {
  [panelA, panelB].forEach(P => {
    pcDisposeChildren(P.probe);
    const dim = pcProbeLocal ? 0.15 : 1.0;
    P.rayMats.forEach(m => { m.opacity = m.userData.base * dim; });
  });
  if (!pcProbeLocal) return;

  pcActive().forEach(P => {
    const W = new THREE.Vector3(WALL_F + 0.02, pcProbeLocal.y, pcProbeLocal.z);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.11, 0.17, 30),
      new THREE.MeshBasicMaterial({ color: 0xff6600, side: THREE.DoubleSide }));
    ring.position.set(WALL_F + 0.04, W.y, W.z);
    ring.rotation.y = Math.PI / 2;
    P.probe.add(ring);

    if (P.mode === 'a') {
      PROBE_SRC.forEach(s => {
        P.probe.add(pcRay(twp(s.l), W, s.c, { shaftR: 0.010, headR: 0.095, headLen: 0.28 }));
      });
    } else {
      const r = pcApertureRadius(pcState.pin);
      const dirv = new THREE.Vector3().subVectors(PIN, W);
      const t = (TREE_X - W.x) / dirv.x;
      const S = W.clone().addScaledVector(dirv, t);
      P.probe.add(pcRay(S, PIN, 0xff6600, { head: false, shaftR: 0.013 }));
      P.probe.add(pcRay(PIN, W, 0xff6600, { shaftR: 0.013, headR: 0.11, headLen: 0.30 }));
      const k = 8;
      for (let i = 0; i < k; i++) {
        const ang = i / k * Math.PI * 2;
        const Hp = new THREE.Vector3(BAR_X, PIN_Y + r * 1.5 * Math.sin(ang), r * Math.cos(ang));
        const d2 = new THREE.Vector3().subVectors(Hp, W);
        const t2 = (TREE_X - W.x) / d2.x;
        const S2 = W.clone().addScaledVector(d2, t2);
        P.probe.add(pcRay(S2, W, 0xffab55, { head: false, shaftR: 0.006, opacity: 0.55 }));
      }
    }
  });
}

/* ── layout / rebuild ──────────────────────────────────────────────────── */
function pcRebuild() {
  const az = THREE.MathUtils.degToRad(AZ_DEG);
  const right = new THREE.Vector3(Math.sin(az), 0, -Math.cos(az));
  [panelA, panelB].forEach(P => { if (P.group.parent) scene.remove(P.group); });
  const act = pcActive();
  if (pcState.layout === 'side') {
    panelA.group.position.copy(right).multiplyScalar(-3.9);
    panelB.group.position.copy(right).multiplyScalar(3.9);
  } else {
    act[0].group.position.set(0, 0, 0);
  }
  act.forEach(P => { scene.add(P.group); P.group.updateMatrixWorld(true); });
  [panelA, panelB].forEach(P => P.group.updateMatrixWorld(true));

  pcUpdateLabels();
  pcApplyProbe();

  if (pcLastLayout !== pcState.layout) {
    pcLastLayout = pcState.layout;
    setCameraView({
      projection: 'perspective',
      azimuthDeg: AZ_DEG, elevationDeg: EL_DEG, rollDeg: 0,
      heightFraction: pcState.layout === 'side' ? 0.66 : 0.78
    });
  }
}

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const bModeA = document.getElementById('btnModeA');
const bModeB = document.getElementById('btnModeB');
const bLay1 = document.getElementById('btnLay1');
const bLay2 = document.getElementById('btnLay2');
const slPin = document.getElementById('slPin');

function pcSyncButtons() {
  bModeA.classList.toggle('active', pcState.mode === 'a');
  bModeB.classList.toggle('active', pcState.mode === 'b');
  bLay1.classList.toggle('active', pcState.layout === 'single');
  bLay2.classList.toggle('active', pcState.layout === 'side');
}

bModeA.addEventListener('click', () => { pcState.mode = 'a'; pcSyncButtons(); pcRebuild(); });
bModeB.addEventListener('click', () => { pcState.mode = 'b'; pcSyncButtons(); pcRebuild(); });
bLay1.addEventListener('click', () => { pcState.layout = 'single'; pcSyncButtons(); pcRebuild(); });
bLay2.addEventListener('click', () => { pcState.layout = 'side'; pcSyncButtons(); pcRebuild(); });
slPin.addEventListener('input', () => {
  pcPinTarget = parseFloat(slPin.value);
  pcPinCur = pcPinTarget;
  pcSetPinhole(pcPinCur);
});
document.getElementById('btnClearProbe').addEventListener('click', () => { pcProbeLocal = null; pcApplyProbe(); });
document.getElementById('btnReset').style.display = '';

/* pinhole tween */
let pcPinTarget = 1, pcPinCur = 1, pcTweening = false;
function pcTick() {
  pcPinCur += (pcPinTarget - pcPinCur) * 0.15;
  if (Math.abs(pcPinTarget - pcPinCur) < 0.01) { pcPinCur = pcPinTarget; pcTweening = false; }
  pcSetPinhole(pcPinCur);
  if (pcTweening) requestAnimationFrame(pcTick);
}
function pcTweenPin(v) {
  pcPinTarget = v;
  if (!pcTweening) { pcTweening = true; requestAnimationFrame(pcTick); }
}

/* ── click-to-probe (own raycast so hidden panels never steal the hit) ─── */
const pcRc = new THREE.Raycaster();
const pcNdc = new THREE.Vector2();
let pcDownX = 0, pcDownY = 0;
canvas.addEventListener('pointerdown', e => { pcDownX = e.clientX; pcDownY = e.clientY; });
canvas.addEventListener('click', e => {
  if (Math.abs(e.clientX - pcDownX) + Math.abs(e.clientY - pcDownY) > 6) return;
  const rect = canvas.getBoundingClientRect();
  pcNdc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pcNdc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  pcRc.setFromCamera(pcNdc, camera);
  const act = pcActive();
  const hits = pcRc.intersectObjects(act.map(P => P.wall), false);
  if (!hits.length) return;
  const P = act.find(p => p.wall === hits[0].object);
  const loc = hits[0].point.clone().sub(P.group.position);
  pcProbeLocal = new THREE.Vector3(WALL_F,
    THREE.MathUtils.clamp(loc.y, -WALL_H / 2 + 0.3, WALL_H / 2 - 0.3),
    THREE.MathUtils.clamp(loc.z, -WALL_D / 2 + 0.3, WALL_D / 2 - 0.3));
  pcApplyProbe();
});

/* ── guided demo ───────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'Bare wall: light from everywhere',
    n: 'Both panels of the figure at once. On the left (a), rays from the trunk, the branches and several canopy blobs all arrive at the same two spots on the wall: every wall point mixes many scene directions, so no picture forms.',
    mode: 'a', layout: 'side', pin: 1, probe: null
  },
  {
    t: 'Probe one wall point',
    n: 'Highlighting a single wall location shows its full incoming bundle — brown rays from the trunk and green rays from the leaves land on the identical spot and average into a uniform glow.',
    mode: 'a', layout: 'single', probe: [1.05, 0.15]
  },
  {
    t: 'Insert the pinhole barrier',
    n: 'A black barrier blocks all paths but one tiny hole. Rays cross at the pinhole, so the top of the tree maps to the bottom of the wall: an inverted image appears.',
    mode: 'b', layout: 'single', pin: 1, probe: null
  },
  {
    t: 'Same wall point, one direction',
    n: 'Side by side, the same wall location receives a fan of directions on the left and a single ray on the right — aperture restriction is the whole mechanism of image formation.',
    mode: 'b', layout: 'side', pin: 1, probe: [1.05, 0.15]
  },
  {
    t: 'Open the hole wider',
    n: 'Widening the pinhole readmits a cone of directions per wall point; the inverted tree smears out and, at the largest setting, approaches the featureless wall of panel (a).',
    mode: 'b', layout: 'single', pin: 10, probe: null
  }
];
let pcStep = 0;
function goToStep(i) {
  pcStep = (i % STEPS.length + STEPS.length) % STEPS.length;
  const s = STEPS[pcStep];
  pcState.mode = s.mode;
  pcState.layout = s.layout;
  pcProbeLocal = s.probe ? new THREE.Vector3(WALL_F, s.probe[0], s.probe[1]) : null;
  if (s.pin != null) pcTweenPin(s.pin);
  document.getElementById('stepTitle').textContent = (pcStep + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
  pcSyncButtons();
  pcRebuild();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(pcStep + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(pcStep - 1));

/* ── boot ──────────────────────────────────────────────────────────────── */
pcSetPinhole(1);
pcSyncButtons();
pcRebuild();
setCameraView({
  projection: 'perspective',
  azimuthDeg: AZ_DEG, elevationDeg: EL_DEG, rollDeg: 0, heightFraction: 0.66
});
goToStep(0);
